package com.crm.customer;
import com.crm.customer.controller.CustomerController;import com.crm.customer.client.CustomerEmployeeDirectory;import com.crm.customer.service.*;import com.crm.customer.dto.CustomerResponse;import com.crm.customer.config.SecurityConfig;import com.crm.security.JwtSecurityAutoConfiguration;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.*;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockMultipartFile;import java.util.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(controllers=CustomerController.class) @Import({SecurityConfig.class,JwtSecurityAutoConfiguration.class,CustomerCsvService.class,CustomerXlsxService.class}) @AutoConfigureMockMvc(addFilters=true,print=MockMvcPrint.NONE)
class CustomerXlsxHttpTest extends com.crm.customer.security.TestIdentitySupport {@Autowired MockMvc mvc;@MockBean ICustomerService customers;@MockBean CustomerEmployeeDirectory directory;
 String bearer(String role){return "Bearer "+token("synthetic","",true,List.of(role));}byte[] workbook()throws Exception{return CustomerXlsxImportTest.archive(CustomerXlsxImportTest.parts(CustomerXlsxImportTest.sheet("name").replace(">email<",">assignedEmployeeId<").replace("sales@example.invalid","101")));}
 @ParameterizedTest @ValueSource(strings={"EMPLOYEE","CLIENT","ADMIN","SUPER_ADMIN"}) void xlsxImportAndRestoreRequireAdministrators(String role)throws Exception{when(customers.createCustomer(any())).thenReturn(new CustomerResponse());boolean admin=role.equals("ADMIN")||role.equals("SUPER_ADMIN");mvc.perform(multipart("/api/customers/import.xlsx").file(new MockMultipartFile("file","contacts.xlsx","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",workbook())).header("Authorization",bearer(role))).andExpect(status().is(admin?200:403));mvc.perform(patch("/api/customers/7/restore").header("Authorization",bearer(role))).andExpect(status().is(admin?200:403));if(admin){verify(directory).requireExisting(eq(101L),anyString());verify(customers).createCustomer(argThat(c->c.getAssignedEmployeeId().equals(101L)));}else verifyNoInteractions(directory,customers);}
 @Test void referenceFailureIsARejectedRowAndNeverCreatesThatContact()throws Exception{doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"private")).when(directory).requireExisting(anyLong(),any());mvc.perform(multipart("/api/customers/import.xlsx").file(new MockMultipartFile("file","contacts.xlsx","application/octet-stream",workbook())).header("Authorization",bearer("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.acceptedRows").value(0)).andExpect(jsonPath("$.rejectedRows").value(1)).andExpect(header().string("Cache-Control","no-store")).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private"))));verifyNoInteractions(customers);}
 @Test void wrongExtensionAndOversizedUploadsFailBeforeReadingWorkbook()throws Exception{mvc.perform(multipart("/api/customers/import.xlsx").file(new MockMultipartFile("file","bad.xlsm","application/octet-stream",new byte[]{1})).header("Authorization",bearer("ADMIN"))).andExpect(status().isBadRequest());mvc.perform(multipart("/api/customers/import.xlsx").file(new MockMultipartFile("file","contacts.xlsx","application/octet-stream",new byte[5*1024*1024+1])).header("Authorization",bearer("ADMIN"))).andExpect(status().isPayloadTooLarge());verifyNoInteractions(customers,directory);}
}
